DROP SCHEMA IF EXISTS conformance_demo CASCADE;
CREATE SCHEMA conformance_demo;

CREATE TABLE conformance_demo.universities (id bigint PRIMARY KEY, name text NOT NULL);
CREATE TABLE conformance_demo.courses (id bigint PRIMARY KEY, name text NOT NULL);
CREATE TABLE conformance_demo.semesters (id bigint PRIMARY KEY, name text NOT NULL);

CREATE TABLE conformance_demo.students (
  id bigint PRIMARY KEY,
  first_name text NOT NULL,
  last_name text NOT NULL,
  display_name text NOT NULL,
  email text,
  email_verified boolean NOT NULL,
  phone text,
  university_id bigint NOT NULL REFERENCES conformance_demo.universities (id),
  course_id bigint REFERENCES conformance_demo.courses (id),
  semester_id bigint REFERENCES conformance_demo.semesters (id),
  signup_date date NOT NULL,
  suppressed boolean NOT NULL,
  whatsapp_consent boolean NOT NULL,
  sms_consent boolean NOT NULL
);

CREATE TABLE conformance_demo.enrollments (
  student_id bigint NOT NULL REFERENCES conformance_demo.students (id),
  course_id bigint NOT NULL REFERENCES conformance_demo.courses (id)
);

CREATE TABLE conformance_demo.devices (
  student_id bigint NOT NULL REFERENCES conformance_demo.students (id),
  token text,
  platform text NOT NULL,
  active boolean NOT NULL
);

CREATE TABLE conformance_demo.purchases (
  student_id bigint NOT NULL REFERENCES conformance_demo.students (id),
  is_active boolean NOT NULL,
  expiry_date date
);

-- The course dimension: the primary course or any enrollment.
CREATE VIEW conformance_demo.student_courses AS
  SELECT id AS student_id, course_id FROM conformance_demo.students WHERE course_id IS NOT NULL
  UNION
  SELECT student_id, course_id FROM conformance_demo.enrollments;







